import { resolveUri } from './getLocationUri.js';
import { isObject } from './objectUtils.js';
import { isUriLocation } from './types/data.js';
/**
 * A value rendered as a display string: a UriLocation as its resolved href, any
 * other object as JSON, everything else via String(). Shared by the DataGrid
 * column-width heuristic and the feature-detail panels.
 */
export function getStr(obj) {
    return isObject(obj)
        ? isUriLocation(obj)
            ? resolveUri(obj)
            : JSON.stringify(obj)
        : String(obj);
}
